/**
 * Tiger Event — Instagram OAuth Token Worker
 * ------------------------------------------
 * ورك منفصل (ما يلمس موقعكم الأساسي) يسوي عملية تسجيل الدخول
 * والحصول على Access Token طويل الأمد لحساب انستقرام tiger4event.
 *
 * المتغيرات المطلوبة (Settings → Variables and Secrets بلوحة Cloudflare):
 *   IG_APP_ID           -> رقم Instagram app ID (من صفحة API setup with Instagram login)
 *   IG_APP_SECRET       -> Instagram app secret (نفس الصفحة) — خليه Secret مو Text عادي
 *   IG_REDIRECT_URI     -> رابط هذا الورك نفسه + /callback
 *   R2_ACCESS_KEY_ID    -> من R2 API Token (Object Read & Write)
 *   R2_SECRET_ACCESS_KEY-> من R2 API Token
 *   R2_ACCOUNT_ID       -> Account ID من لوحة Cloudflare
 *   ANTHROPIC_API_KEY   -> مفتاح Claude API (لتوليد الكابشن تلقائيًا)
 *
 * النشر التلقائي (بدون تدخل يدوي):
 *   ارفع 4 صور جاهزة لـ R2 باسم: templates-wedding.jpg / templates-event.jpg /
 *   templates-production.jpg / templates-conference.jpg
 *   الكرون (كل 15 دقيقة) ينشر تلقائيًا بوست واحد كل أسبوعين، يوم الأحد الساعة
 *   6 مساءً بتوقيت الكويت، يختار الفئة بالتناوب، ويولّد الكابشن عبر Claude.
 *
 * لوحة التحكم الموحدة:
 *   /dashboard -> واجهة واحدة (مكتبة + AI Studio + جدول + تحليلات + إعدادات)
 *   تتصل بنفس الـ endpoints أدناه. الصفحات القديمة /new و /schedule ضلت
 *   شغالة كما هي (fallback) ولم يُمسّ أي شيء منها.
 */

import { AwsClient } from "aws4fetch";

const WORKER_HOST = "tiger-ig-token2.mohdjarour.workers.dev";
const R2_BUCKET_NAME = "tiger-ig-images";

const CATEGORIES = ["wedding", "event", "production", "conference"];
const CATEGORY_LABELS_AR = {
  wedding: "الأعراس",
  event: "الفعاليات والتنظيم",
  production: "البرودكشن",
  conference: "المؤتمرات",
};
const TONE_LABELS_AR = {
  luxury: "فاخر واحترافي",
  energetic: "حماسي وشبابي",
  clean: "مختصر وواضح",
};
const POST_TYPE_LABELS_AR = { reel: "Reel", post: "منشور", story: "ستوري" };

/* ------------------------- محرر البوستات (Tiger Social Editor) -------------------------
 * أداة مستقلة بالكامل تشتغل بالمتصفح (React عبر CDN + JSZip) — بدون أي اتصال
 * بأي سيرفر، رفعت كملفاتها الأصلية زي ما هي (base64) وتنقرأ عبر /editor/*.
 * محمّلة داخل لوحة التحكم بإطار (iframe) بتبويب "محرر البوستات" — ما تحتاج
 * أي شيء من env (IG_ACCESS_TOKEN, DB, R2...)، فهي منفصلة تمامًا عن باقي النظام.
 */
const EDITOR_FILES = {
  "index.html": { type: "text/html; charset=UTF-8", b64: "" },
  "app.js": { type: "application/javascript; charset=UTF-8", b64: "" },
  "icons.js": { type: "application/javascript; charset=UTF-8", b64: "" },
  "manifest.json": { type: "application/manifest+json; charset=UTF-8", b64: "" },
  "sw.js": { type: "application/javascript; charset=UTF-8", b64: "" },
  "icons/icon-192.png": { type: "image/png", b64: "" },
  "icons/icon-512.png": { type: "image/png", b64: "" },
};

function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

function b64ToText(b64) {
  return new TextDecoder("utf-8").decode(b64ToBytes(b64));
}


/* ------------------------- إعدادات النشر التلقائي -------------------------
 * مجمّعة هنا بدل ما تكون أرقامًا مبعثرة داخل الدوال: تغيير الوتيرة صار سطرًا
 * واحدًا. AUTO_MIN_GAP_DAYS خُلّي 13 مو 14 عن قصد — الفاصل يُقاس من وقت آخر
 * نشر فعلي، فلو تأخر بوست بضع ساعات (خطأ مؤقت، توكن منتهي) كان الفاصل الكامل
 * راح يزحف ويأجل النشر أسبوعًا كاملًا بلا داعٍ.
 */
const AUTO_PUBLISH_DAY = 0;      // 0 = الأحد (يوم الأسبوع بتوقيت UTC)
const AUTO_PUBLISH_HOUR_KW = 18; // 6 مساءً بتوقيت الكويت
const AUTO_MIN_GAP_DAYS = 13;    // أسبوعان تقريبًا بين كل بوست تلقائي

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/" || url.pathname === "") {
      return html(`
        <h1>Tiger Event — أداة توكن انستقرام</h1>
        <p>اضغط الزر تحت وسجل دخول بحساب <b>tiger4event</b>.</p>
        <a class="btn" href="/start">تسجيل الدخول وربط الحساب</a>
        <p class="note" style="margin-top:22px;">أو افتح <a href="/dashboard" style="color:#F8A337;">لوحة التحكم الموحدة</a> لو التوكن مربوط أصلاً.</p>
      `);
    }

    if (url.pathname === "/start") {
      if (!env.IG_APP_ID || !env.IG_REDIRECT_URI) {
        return html(errorBlock("متغيرات الإعداد ناقصة", "لازم تضيف IG_APP_ID و IG_REDIRECT_URI بإعدادات الورك أول."));
      }
      const scope = [
        "instagram_business_basic",
        "instagram_business_manage_messages",
        "instagram_business_manage_comments",
        "instagram_business_content_publish",
        "instagram_business_manage_insights",
      ].join(",");

      const authUrl =
        "https://www.instagram.com/oauth/authorize" +
        `?client_id=${encodeURIComponent(env.IG_APP_ID)}` +
        `&redirect_uri=${encodeURIComponent(env.IG_REDIRECT_URI)}` +
        `&response_type=code` +
        `&scope=${encodeURIComponent(scope)}`;

      return Response.redirect(authUrl, 302);
    }

    if (url.pathname === "/callback") {
      const code = url.searchParams.get("code");
      const errDesc = url.searchParams.get("error_description");

      if (errDesc) {
        return html(errorBlock("انستقرام رفض تسجيل الدخول", errDesc));
      }
      if (!code) {
        return html(errorBlock("ما وصل كود", "الرابط ما فيه ?code= — جرب ترجع لصفحة /start من جديد."));
      }

      try {
        const form = new FormData();
        form.append("client_id", env.IG_APP_ID);
        form.append("client_secret", env.IG_APP_SECRET);
        form.append("grant_type", "authorization_code");
        form.append("redirect_uri", env.IG_REDIRECT_URI);
        form.append("code", code);

        const shortRes = await fetch("https://api.instagram.com/oauth/access_token", {
          method: "POST",
          body: form,
        });
        const shortData = await shortRes.json();

        if (!shortRes.ok || !shortData.access_token) {
          return html(errorBlock("فشلت خطوة 1 (الحصول على توكن قصير)", JSON.stringify(shortData, null, 2)));
        }

        const exchangeUrl =
          "https://graph.instagram.com/access_token" +
          "?grant_type=ig_exchange_token" +
          `&client_secret=${encodeURIComponent(env.IG_APP_SECRET)}` +
          `&access_token=${encodeURIComponent(shortData.access_token)}`;

        const longRes = await fetch(exchangeUrl);
        const longData = await longRes.json();

        if (!longRes.ok || !longData.access_token) {
          return html(errorBlock("فشلت خطوة 2 (تحويل لتوكن طويل)", JSON.stringify(longData, null, 2)));
        }

        const expiresInDays = Math.round((longData.expires_in || 0) / 86400);

        return html(`
          <h1>تم بنجاح ✅</h1>
          <p>هذا التوكن الطويل (صالح تقريبًا ${expiresInDays} يوم). انسخه واحفظه كـ Secret باسم <b>IG_ACCESS_TOKEN</b> بإعدادات الورك، لأنه ما يظهر لك مرة ثانية.</p>
          <textarea readonly onclick="this.select()">${longData.access_token}</textarea>
          <p class="note">بعد ما تحفظه، هذي الصفحة ما راح تحتاجها إلا لو التوكن انتهى بعد 60 يوم وتبي تجدده.</p>
        `);
      } catch (e) {
        return html(errorBlock("خطأ غير متوقع", String(e)));
      }
    }

    if (url.pathname === "/publish") {
      if (!env.IG_ACCESS_TOKEN) {
        return html(errorBlock("التوكن ناقص", "أضف IG_ACCESS_TOKEN بإعدادات الورك أول."));
      }
      const imageUrl = url.searchParams.get("image_url");
      const caption = url.searchParams.get("caption") || "";
      if (!imageUrl) {
        return html(errorBlock("رابط الصورة ناقص", "استخدم ?image_url=...&caption=..."));
      }

      try {
        const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
        const meData = await meRes.json();
        if (!meData.id) {
          return html(errorBlock("ما قدرنا نجيب معرف الحساب", JSON.stringify(meData, null, 2)));
        }

        const containerRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media`, {
          method: "POST",
          body: new URLSearchParams({
            image_url: imageUrl,
            caption: caption,
            access_token: env.IG_ACCESS_TOKEN,
          }),
        });
        const containerData = await containerRes.json();
        if (!containerData.id) {
          return html(errorBlock("فشل إنشاء الحاوية", JSON.stringify(containerData, null, 2)));
        }

        const publishRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media_publish`, {
          method: "POST",
          body: new URLSearchParams({
            creation_id: containerData.id,
            access_token: env.IG_ACCESS_TOKEN,
          }),
        });
        const publishData = await publishRes.json();
        if (!publishData.id) {
          return html(errorBlock("فشل النشر", JSON.stringify(publishData, null, 2)));
        }

        return html(`<h1>✅ تم النشر بنجاح</h1><p>Post ID: ${publishData.id}</p>`);
      } catch (e) {
        return html(errorBlock("خطأ غير متوقع بالنشر", String(e)));
      }
    }

    if (url.pathname === "/new") {
      return html(`
        <h1>Tiger Event — نشر جديد</h1>
        <p>قالب كابشن جاهز:</p>
        <select id="preset" style="width:100%;padding:10px;border-radius:8px;">
          <option value="">— اختر قالب (اختياري) —</option>
          <option value="wedding">أعراس</option>
          <option value="event">فعاليات وتنظيم</option>
          <option value="production">برودكشن</option>
          <option value="conference">مؤتمرات</option>
        </select>
        <p>اختر الصورة أو الفيديو:</p>
        <input type="file" id="img" accept="image/*,video/*" required>
        <p>الكابشن:</p>
        <textarea id="cap" placeholder="اكتب الكابشن هنا أو اختر قالب جاهز..." style="min-height:140px;"></textarea>
        <button type="button" id="publishBtn" class="btn" style="border:none;cursor:pointer;">نشر الآن</button>
        <div id="status" style="margin-top:16px;"></div>
        <script>
          const presets = {
            wedding: "✨ عروسين اليوم مميزين ونحرص نخلي كل تفصيلة بمناسبتكم بأحلى صورة 💍\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #أعراس #تنظيم_أعراس #الكويت",
            event: "🎉 فعالية جديدة ننظمها بكل التفاصيل من الألف للياء\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #تنظيم_فعاليات #الكويت #event_management",
            production: "🎬 خلف الكواليس... فريقنا شغال على إنتاج يليق بالمناسبة\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #برودكشن #production #الكويت",
            conference: "🎤 مؤتمر ناجح يبدأ بتنظيم احترافي، وهذا شغلنا بالضبط\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #مؤتمرات #conferences #الكويت"
          };
          document.getElementById('preset').addEventListener('change', function(){
            const val = presets[this.value];
            if (val) document.getElementById('cap').value = val;
          });

          async function pollStatus(containerId){
            const statusDiv = document.getElementById('status');
            let tries = 0;
            while (tries < 40) {
              await new Promise(function(r){ setTimeout(r, 3000); });
              const res = await fetch('/publish-status?id=' + containerId);
              const data = await res.json();
              if (data.status === 'FINISHED') return;
              if (data.status === 'ERROR') throw new Error('فشلت معالجة الفيديو');
              statusDiv.innerHTML = '<p>⏳ جاري معالجة الفيديو...</p>';
              tries++;
            }
            throw new Error('استغرقت المعالجة وقت طويل');
          }

          document.getElementById('publishBtn').addEventListener('click', async function(){
            const btn = this;
            if (btn.disabled) return;
            const fileInput = document.getElementById('img');
            const caption = document.getElementById('cap');
            const statusDiv = document.getElementById('status');
            if (!fileInput.files[0]) return;
            btn.disabled = true;
            statusDiv.innerHTML = '<p>⏳ جاري الرفع...</p>';
            const formData = new FormData();
            formData.append('image', fileInput.files[0]);
            formData.append('caption', caption.value);
            try {
              const res = await fetch('/upload-and-publish', { method: 'POST', body: formData });
              const data = await res.json();
              if (!data.success) {
                statusDiv.innerHTML = '<pre>' + JSON.stringify(data, null, 2) + '</pre>';
                return;
              }
              if (data.isVideo) {
                await pollStatus(data.containerId);
              }
              statusDiv.innerHTML = '<p>⏳ جاري النشر النهائي... (id: ' + data.containerId + ')</p>';
              const finalRes = await fetch('/finalize?id=' + data.containerId);
              const finalData = await finalRes.json();
              if (finalData.success) {
                statusDiv.innerHTML = '<h1>✅ تم النشر بنجاح</h1><p>Post ID: ' + finalData.postId + '</p>';
              } else {
                statusDiv.innerHTML = '<pre>' + JSON.stringify(finalData, null, 2) + '</pre>';
              }
            } catch (err) {
              statusDiv.innerHTML = '<pre>خطأ: ' + String(err) + '</pre>';
            } finally {
              btn.disabled = false;
            }
          });
        </script>
      `);
    }

    if (url.pathname === "/schedule") {
      return html(`
        <h1>Tiger Event — جدولة بوست</h1>
        <p>قالب كابشن جاهز:</p>
        <select id="preset" style="width:100%;padding:10px;border-radius:8px;">
          <option value="">— اختر قالب (اختياري) —</option>
          <option value="wedding">أعراس</option>
          <option value="event">فعاليات وتنظيم</option>
          <option value="production">برودكشن</option>
          <option value="conference">مؤتمرات</option>
        </select>
        <p>اختر الصورة أو الفيديو:</p>
        <input type="file" id="img" accept="image/*,video/*" required>
        <p>الكابشن:</p>
        <textarea id="cap" placeholder="اكتب الكابشن هنا أو اختر قالب جاهز..." style="min-height:140px;"></textarea>
        <p>وقت النشر:</p>
        <input type="datetime-local" id="dt" style="width:100%;padding:10px;border-radius:8px;">
        <button type="button" id="saveBtn" class="btn" style="border:none;cursor:pointer;">جدولة البوست</button>
        <div id="status" style="margin-top:16px;"></div>
        <script>
          const presets = {
            wedding: "✨ عروسين اليوم مميزين ونحرص نخلي كل تفصيلة بمناسبتكم بأحلى صورة 💍\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #أعراس #تنظيم_أعراس #الكويت",
            event: "🎉 فعالية جديدة ننظمها بكل التفاصيل من الألف للياء\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #تنظيم_فعاليات #الكويت #event_management",
            production: "🎬 خلف الكواليس... فريقنا شغال على إنتاج يليق بالمناسبة\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #برودكشن #production #الكويت",
            conference: "🎤 مؤتمر ناجح يبدأ بتنظيم احترافي، وهذا شغلنا بالضبط\\n\\n📍 الكويت\\n📩 تواصل معنا الحين\\n\\n#TigerEvent #مؤتمرات #conferences #الكويت"
          };
          document.getElementById('preset').addEventListener('change', function(){
            const val = presets[this.value];
            if (val) document.getElementById('cap').value = val;
          });
          document.getElementById('saveBtn').addEventListener('click', async function(){
            const btn = this;
            if (btn.disabled) return;
            const fileInput = document.getElementById('img');
            const caption = document.getElementById('cap').value;
            const dtLocal = document.getElementById('dt').value;
            const dt = dtLocal ? new Date(dtLocal).toISOString().slice(0, 16) : '';
            const statusDiv = document.getElementById('status');
            const file = fileInput.files[0];
            if (!file || !dt) {
              statusDiv.innerHTML = '<p>لازم تختار ملف ووقت النشر</p>';
              return;
            }
            btn.disabled = true;
            try {
              statusDiv.innerHTML = '<p>⏳ جاري تجهيز الرفع...</p>';
              const urlRes = await fetch('/get-upload-url', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ filename: file.name, contentType: file.type })
              });
              const urlData = await urlRes.json();
              if (!urlData.success) {
                statusDiv.innerHTML = '<pre>' + JSON.stringify(urlData, null, 2) + '</pre>';
                return;
              }

              statusDiv.innerHTML = '<p>⏳ جاري رفع الملف مباشرة...</p>';
              const putRes = await fetch(urlData.uploadUrl, {
                method: 'PUT',
                headers: { 'Content-Type': file.type },
                body: file
              });
              if (!putRes.ok) {
                statusDiv.innerHTML = '<p>فشل الرفع (كود ' + putRes.status + ')</p>';
                return;
              }

              statusDiv.innerHTML = '<p>⏳ جاري الحفظ...</p>';
              const res = await fetch('/save-schedule', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                  key: urlData.key,
                  media_type: file.type.startsWith('video/') ? 'video' : 'image',
                  caption: caption,
                  scheduled_time: dt
                })
              });
              const data = await res.json();
              if (data.success) {
                statusDiv.innerHTML = '<h1>✅ تم جدولة البوست</h1><p>هينشر تلقائيًا بالوقت المحدد</p>';
              } else {
                statusDiv.innerHTML = '<pre>' + JSON.stringify(data, null, 2) + '</pre>';
              }
            } catch (err) {
              statusDiv.innerHTML = '<pre>خطأ: ' + String(err) + '</pre>';
            } finally {
              btn.disabled = false;
            }
          });
        </script>
      `);
    }

    if (url.pathname === "/get-upload-url" && request.method === "POST") {
      if (!env.R2_ACCESS_KEY_ID || !env.R2_SECRET_ACCESS_KEY || !env.R2_ACCOUNT_ID) {
        return json({ success: false, error: "إعداد الرفع المباشر ناقص (R2_ACCESS_KEY_ID / R2_SECRET_ACCESS_KEY / R2_ACCOUNT_ID)" });
      }
      try {
        const { filename, contentType } = await request.json();
        const ext = (filename || "file").split(".").pop() || "bin";
        const key = `posts/${Date.now()}.${ext}`;
        const client = new AwsClient({
          accessKeyId: env.R2_ACCESS_KEY_ID,
          secretAccessKey: env.R2_SECRET_ACCESS_KEY,
        });
        const endpoint = `https://${env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com/${R2_BUCKET_NAME}/${key}`;
        const signed = await client.sign(endpoint, {
          method: "PUT",
          headers: { "Content-Type": contentType || "application/octet-stream" },
          aws: { signQuery: true },
        });
        return json({ success: true, uploadUrl: signed.url, key });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/save-schedule") {
      if (!env.DB) {
        return json({ success: false, error: "الإعداد ناقص (DB)" });
      }
      try {
        const body = await request.json();
        const key = body.key;
        const mediaType = body.media_type || "image";
        const caption = body.caption || "";
        const scheduledTime = body.scheduled_time;
        if (!key || !scheduledTime) {
          return json({ success: false, error: "بيانات ناقصة" });
        }

        await env.DB.prepare(
          "INSERT INTO scheduled_posts (media_key, media_type, caption, scheduled_time) VALUES (?, ?, ?, ?)"
        ).bind(key, mediaType, caption, scheduledTime).run();

        return json({ success: true });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/upload-and-publish") {
      if (!env.IG_ACCESS_TOKEN || !env.IMAGES) {
        return json({ success: false, error: "الإعداد ناقص (توكن أو R2)" });
      }
      try {
        const formData = await request.formData();
        const file = formData.get("image");
        const caption = formData.get("caption") || "";
        if (!file) {
          return json({ success: false, error: "ما وصلت صورة" });
        }

        const ext = file.name.split(".").pop() || "jpg";
        const key = `posts/${Date.now()}.${ext}`;
        await env.IMAGES.put(key, file.stream(), { httpMetadata: { contentType: file.type } });

        const imageUrl = `https://${url.hostname}/img/${key}`;

        const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
        const meData = await meRes.json();
        if (!meData.id) {
          return json({ success: false, error: "معرف الحساب", detail: meData });
        }

        const isVideo = file.type.startsWith("video/");
        const containerParams = isVideo
          ? { media_type: "REELS", video_url: imageUrl, caption: caption, access_token: env.IG_ACCESS_TOKEN }
          : { image_url: imageUrl, caption: caption, access_token: env.IG_ACCESS_TOKEN };

        const containerRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media`, {
          method: "POST",
          body: new URLSearchParams(containerParams),
        });
        const containerData = await containerRes.json();
        if (!containerData.id) {
          return json({ success: false, error: "إنشاء الحاوية", detail: containerData });
        }

        return json({ success: true, containerId: containerData.id, isVideo: isVideo });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/publish-status") {
      const id = url.searchParams.get("id");
      if (!env.IG_ACCESS_TOKEN || !id) {
        return json({ status: "ERROR" });
      }
      try {
        const statusRes = await fetch(`https://graph.instagram.com/v21.0/${id}?fields=status_code&access_token=${env.IG_ACCESS_TOKEN}`);
        const statusData = await statusRes.json();
        return json({ status: statusData.status_code || "ERROR" });
      } catch (e) {
        return json({ status: "ERROR", error: String(e) });
      }
    }

    if (url.pathname === "/finalize") {
      const id = url.searchParams.get("id");
      if (!env.IG_ACCESS_TOKEN || !id) {
        return json({ success: false, error: "بيانات ناقصة" });
      }
      try {
        const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
        const meData = await meRes.json();
        if (!meData.id) {
          return json({ success: false, error: "معرف الحساب", detail: meData });
        }
        const publishRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media_publish`, {
          method: "POST",
          body: new URLSearchParams({ creation_id: id, access_token: env.IG_ACCESS_TOKEN }),
        });
        const publishData = await publishRes.json();
        if (!publishData.id) {
          return json({ success: false, error: "النشر", detail: publishData });
        }
        return json({ success: true, postId: publishData.id });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    // نشر تلقائي فوري للتجربة (يفتح من المتصفح بدون انتظار الكرون)
    if (url.pathname === "/auto-test") {
      try {
        const result = await autoPublishNext(env);
        return html(`<h1>✅ تم النشر التلقائي</h1><pre>${escapeHtml(JSON.stringify(result, null, 2))}</pre>`);
      } catch (e) {
        return html(errorBlock("فشل النشر التلقائي", String(e)));
      }
    }

    // متى البوست التلقائي الجاي؟ صفحة قراءة فقط — بدونها الطريقة الوحيدة لمعرفة
    // إن النظام شغال هي انتظار ظهور بوست على الحساب.
    if (url.pathname === "/auto-status") {
      if (!env.DB) return html(errorBlock("الإعداد ناقص", "DB مو مربوط."));
      try {
        const last = await env.DB.prepare(
          "SELECT scheduled_time, caption FROM scheduled_posts WHERE caption LIKE '%[auto]%' ORDER BY id DESC LIMIT 1"
        ).first();
        const countRow = await env.DB.prepare(
          "SELECT COUNT(*) AS n FROM scheduled_posts WHERE caption LIKE '%[auto]%'"
        ).first();
        const n = (countRow && countRow.n) || 0;
        const nextCat = CATEGORIES[n % CATEGORIES.length];
        const lastTxt = last ? last.scheduled_time : "ما فيه بوست تلقائي بعد";
        const eligible = last
          ? new Date(new Date(last.scheduled_time + ":00Z").getTime() + AUTO_MIN_GAP_DAYS * 86400000)
          : new Date();
        return html(`
          <h1>حالة النشر التلقائي</h1>
          <p>الوتيرة: بوست واحد كل أسبوعين — الأحد الساعة ${AUTO_PUBLISH_HOUR_KW}:00 بتوقيت الكويت.</p>
          <p>عدد البوستات التلقائية حتى الآن: <b>${n}</b></p>
          <p>آخر بوست تلقائي: <b>${escapeHtml(lastTxt)}</b> (UTC)</p>
          <p>ما ينشر قبل: <b>${escapeHtml(eligible.toISOString().slice(0, 16))}</b> (UTC)، وأول أحد بعدها الساعة 6 مساءً.</p>
          <p>الفئة الجاية بالدور: <b>${CATEGORY_LABELS_AR[nextCat]}</b></p>
          <p class="note">للنشر فورًا بدون انتظار: <a href="/auto-test" style="color:#F8A337;">/auto-test</a></p>
        `);
      } catch (e) {
        return html(errorBlock("خطأ", String(e)));
      }
    }

    /* ---------------------------------------------------------------------
     * لوحة التحكم الموحدة + الـ API الخاص فيها. كل شي تحت هون جديد، وكله
     * يستخدم نفس المتغيرات ونفس جداول D1 ونفس bucket الـ R2 الموجودة أصلاً.
     * --------------------------------------------------------------------- */

    if (url.pathname === "/dashboard") {
      return new Response(renderDashboard(), {
        headers: { "content-type": "text/html; charset=UTF-8" },
      });
    }

    /* -------- الهوية البصرية: شعار + أيقونات + إمكانية التثبيت (PWA) --------
     * الملفات (logo.png, icon-*.png, favicon.ico) تترفع مرة وحدة عبر
     * /admin/brand لنفس bucket الـ R2 الموجود (IMAGES) تحت مفتاح "brand/..."،
     * وتُقرأ بعدين تلقائيًا عبر /img/brand/... (نفس مسار /img/ العام الموجود
     * أصلاً بالأسفل، ما احتجنا مسار جديد للقراءة).
     */

    if (url.pathname === "/admin/brand") {
      return html(`
        <h1>رفع ملفات الهوية البصرية</h1>
        <p>ارفع كل ملف بمكانه الصحيح — الاسم يتحدد تلقائيًا حسب الاختيار.</p>
        <select id="assetKey" style="width:100%;padding:10px;border-radius:8px;margin-bottom:10px;">
          <option value="logo.png">الشعار الكامل (logo.png)</option>
          <option value="icon-512.png">أيقونة 512×512 (icon-512.png)</option>
          <option value="icon-192.png">أيقونة 192×192 (icon-192.png)</option>
          <option value="icon-180.png">أيقونة آيفون 180×180 (icon-180.png)</option>
          <option value="favicon.ico">أيقونة المتصفح (favicon.ico)</option>
        </select>
        <input type="file" id="assetFile" accept="image/*,.ico">
        <button type="button" id="uploadBtn" class="btn" style="border:none;cursor:pointer;margin-top:12px;">رفع الملف</button>
        <div id="status" style="margin-top:16px;"></div>
        <script>
          document.getElementById('uploadBtn').addEventListener('click', async function(){
            const btn = this;
            const key = document.getElementById('assetKey').value;
            const file = document.getElementById('assetFile').files[0];
            const statusDiv = document.getElementById('status');
            if (!file) { statusDiv.innerHTML = '<p>اختر ملف أول</p>'; return; }
            btn.disabled = true;
            statusDiv.innerHTML = '<p>⏳ جاري الرفع...</p>';
            const formData = new FormData();
            formData.append('key', key);
            formData.append('file', file);
            try {
              const res = await fetch('/admin/upload-brand', { method: 'POST', body: formData });
              const data = await res.json();
              if (data.success) {
                statusDiv.innerHTML = '<h1>✅ تم الرفع</h1><p>' + key + ' — <a href="/img/brand/' + key + '" target="_blank" style="color:#F8A337;">معاينة</a></p>';
              } else {
                statusDiv.innerHTML = '<pre>' + JSON.stringify(data, null, 2) + '</pre>';
              }
            } catch (err) {
              statusDiv.innerHTML = '<pre>خطأ: ' + String(err) + '</pre>';
            } finally {
              btn.disabled = false;
            }
          });
        </script>
      `);
    }

    if (url.pathname === "/admin/upload-brand" && request.method === "POST") {
      if (!env.IMAGES) return json({ success: false, error: "R2 مو مربوط (IMAGES)" });
      try {
        const formData = await request.formData();
        const key = formData.get("key");
        const file = formData.get("file");
        const allowedKeys = ["logo.png", "icon-512.png", "icon-192.png", "icon-180.png", "favicon.ico"];
        if (!key || !allowedKeys.includes(key)) return json({ success: false, error: "اسم ملف غير مسموح" });
        if (!file) return json({ success: false, error: "ما وصل ملف" });
        await env.IMAGES.put(`brand/${key}`, file.stream(), {
          httpMetadata: { contentType: file.type || "application/octet-stream" },
        });
        return json({ success: true, key });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/manifest.json") {
      const manifest = {
        name: "Tiger AI Studio",
        short_name: "Tiger Event",
        description: "لوحة تحكم Tiger Event لإدارة ونشر محتوى إنستقرام",
        start_url: "/dashboard",
        scope: "/",
        display: "standalone",
        background_color: "#0B1A2E",
        theme_color: "#0B1A2E",
        lang: "ar",
        dir: "rtl",
        icons: [
          { src: "/img/brand/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
          { src: "/img/brand/icon-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
          { src: "/img/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
          { src: "/img/brand/icon-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
        ],
      };
      return new Response(JSON.stringify(manifest), {
        headers: { "content-type": "application/manifest+json; charset=UTF-8" },
      });
    }

    if (url.pathname === "/sw.js") {
      const sw = `
        self.addEventListener('install', function(e){ self.skipWaiting(); });
        self.addEventListener('activate', function(e){ self.clients.claim(); });
        self.addEventListener('fetch', function(e){
          // بدون كاش فعلي حاليًا — بس كافي لتحقيق شرط "قابل للتثبيت" بالمتصفح.
          e.respondWith(fetch(e.request).catch(function(){ return new Response('', { status: 503 }); }));
        });
      `;
      return new Response(sw, { headers: { "content-type": "application/javascript; charset=UTF-8" } });
    }

    if (url.pathname === "/api/stats") {
      if (!env.DB) return json({ success: false, error: "DB مو مربوط" });
      try {
        const totalRow = await env.DB.prepare("SELECT COUNT(*) AS n FROM scheduled_posts").first();
        const postedRow = await env.DB.prepare("SELECT COUNT(*) AS n FROM scheduled_posts WHERE status='posted'").first();
        const pendingRow = await env.DB.prepare("SELECT COUNT(*) AS n FROM scheduled_posts WHERE status='pending'").first();
        const failedRow = await env.DB.prepare("SELECT COUNT(*) AS n FROM scheduled_posts WHERE status='failed'").first();
        const autoCountRow = await env.DB.prepare("SELECT COUNT(*) AS n FROM scheduled_posts WHERE caption LIKE '%[auto]%'").first();

        let mediaCount = 0;
        if (env.IMAGES) {
          const listed = await env.IMAGES.list({ prefix: "posts/", limit: 1000 });
          mediaCount = listed.objects.length;
        }

        const autoCount = (autoCountRow && autoCountRow.n) || 0;
        const nextCat = CATEGORIES[autoCount % CATEGORIES.length];

        return json({
          success: true,
          media: mediaCount,
          total: (totalRow && totalRow.n) || 0,
          posted: (postedRow && postedRow.n) || 0,
          pending: (pendingRow && pendingRow.n) || 0,
          failed: (failedRow && failedRow.n) || 0,
          nextAutoCategory: CATEGORY_LABELS_AR[nextCat],
        });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/api/schedule-list") {
      if (!env.DB) return json({ success: false, error: "DB مو مربوط" });
      try {
        const { results } = await env.DB.prepare(
          "SELECT id, media_key, media_type, caption, scheduled_time, status, post_id, error_message FROM scheduled_posts ORDER BY id DESC LIMIT 50"
        ).all();
        return json({ success: true, items: results });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/api/media-list") {
      if (!env.IMAGES) return json({ success: false, error: "R2 مو مربوط" });
      try {
        const listed = await env.IMAGES.list({ prefix: "posts/", limit: 60 });
        const items = listed.objects
          .sort((a, b) => new Date(b.uploaded || 0) - new Date(a.uploaded || 0))
          .map((o) => ({
            key: o.key,
            url: `/img/${o.key}`,
            size: o.size,
            uploaded: o.uploaded,
            isVideo: /\.(mp4|mov|webm|m4v)$/i.test(o.key),
          }));
        return json({ success: true, items });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/api/generate-caption" && request.method === "POST") {
      if (!env.ANTHROPIC_API_KEY) return json({ success: false, error: "ANTHROPIC_API_KEY ناقص بإعدادات الورك" });
      try {
        const body = await request.json();
        const brief = (body.brief || "").trim();
        const tone = body.tone || "luxury";
        const postType = body.postType || "post";
        if (!brief) return json({ success: false, error: "لازم تكتب وصف الفعالية" });
        const caption = await generateFreeCaption(env, brief, tone, postType);
        return json({ success: true, caption });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/api/publish-existing" && request.method === "POST") {
      if (!env.IG_ACCESS_TOKEN) return json({ success: false, error: "التوكن ناقص (IG_ACCESS_TOKEN)" });
      try {
        const body = await request.json();
        const key = body.key;
        const caption = body.caption || "";
        const mediaType = body.media_type || "image";
        if (!key) return json({ success: false, error: "مفتاح الملف ناقص" });
        const result = await publishMediaKey(env, key, mediaType, caption);
        return json({ success: true, postId: result.postId });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/editor" || url.pathname === "/editor/") {
      const f = EDITOR_FILES["index.html"];
      return new Response(b64ToText(f.b64), { headers: { "content-type": f.type } });
    }

    if (url.pathname.startsWith("/editor/")) {
      const key = url.pathname.replace("/editor/", "");
      const f = EDITOR_FILES[key];
      if (!f) return new Response("Not found", { status: 404 });
      if (f.type.startsWith("image/")) {
        return new Response(b64ToBytes(f.b64), { headers: { "content-type": f.type } });
      }
      return new Response(b64ToText(f.b64), { headers: { "content-type": f.type } });
    }

    if (url.pathname === "/api/account-insights") {
      if (!env.IG_ACCESS_TOKEN) return json({ success: false, error: "التوكن ناقص (IG_ACCESS_TOKEN)" });
      try {
        const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
        const meData = await meRes.json();
        if (!meData.id) return json({ success: false, error: "معرف الحساب", detail: meData });

        const metrics = "reach,views,accounts_engaged,total_interactions,follower_count";
        const insRes = await fetch(
          `https://graph.instagram.com/v22.0/${meData.id}/insights?metric=${metrics}&period=days_28&access_token=${env.IG_ACCESS_TOKEN}`
        );
        const insData = await insRes.json();
        if (!insData.data) {
          return json({
            success: false,
            error: "فشل جلب التحليلات — غالبًا التوكن ما فيه صلاحية instagram_business_manage_insights بعد. أعد تسجيل الدخول من /start.",
            detail: insData,
          });
        }

        const result = {};
        for (const m of insData.data) {
          const val = m.values && m.values.length ? m.values[m.values.length - 1].value : null;
          result[m.name] = val;
        }
        return json({ success: true, period: "آخر 28 يوم", metrics: result });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname === "/api/media-insights") {
      const postId = url.searchParams.get("post_id");
      if (!env.IG_ACCESS_TOKEN) return json({ success: false, error: "التوكن ناقص (IG_ACCESS_TOKEN)" });
      if (!postId) return json({ success: false, error: "post_id ناقص" });
      try {
        const metrics = "reach,likes,comments,saved,shares,total_interactions,views";
        const insRes = await fetch(
          `https://graph.instagram.com/v22.0/${postId}/insights?metric=${metrics}&access_token=${env.IG_ACCESS_TOKEN}`
        );
        const insData = await insRes.json();
        if (!insData.data) {
          return json({ success: false, error: "فشل جلب إحصائيات المنشور", detail: insData });
        }
        const result = {};
        for (const m of insData.data) {
          const val = m.values && m.values.length ? m.values[0].value : (m.total_value ? m.total_value.value : null);
          result[m.name] = val;
        }
        return json({ success: true, metrics: result });
      } catch (e) {
        return json({ success: false, error: String(e) });
      }
    }

    if (url.pathname.startsWith("/img/")) {
      const key = url.pathname.replace("/img/", "");
      const obj = await env.IMAGES.get(key);
      if (!obj) return new Response("Not found", { status: 404 });
      return new Response(obj.body, { headers: { "content-type": obj.httpMetadata?.contentType || "image/jpeg" } });
    }
    return html(errorBlock("الصفحة مو موجودة", "جرب /dashboard أو /start"));
  },

  async scheduled(event, env, ctx) {
    // الكرون كل 15 دقيقة: ينشر البوستات المجدولة يدويًا اللي حان وقتها
    ctx.waitUntil(runScheduledPosts(env));
    // ونفس الاستدعاء يفحص هل حان وقت البوست التلقائي (كل أسبوعين)
    ctx.waitUntil(maybeAutoPublish(env));
  },
};

/* ينشر تلقائيًا بوست واحد كل أسبوعين، الأحد الساعة 6 مساءً بتوقيت الكويت.
 *
 * الفاصل يُقاس من وقت آخر بوست تلقائي فعلي، لا من التقويم: لو فات موعد بسبب
 * خطأ مؤقت أو توكن منتهي، ينشر بأول موعد جاي بدل ما ينتظر دورة كاملة ثانية.
 * وهذا الفحص نفسه هو اللي يمنع التكرار — الكرون يشتغل كل 15 دقيقة فيتحقق شرط
 * الساعة أربع مرات، لكن أول نشر ناجح يقفل الباب على الثلاثة الباقية.
 */
async function maybeAutoPublish(env) {
  const now = new Date();
  const kuwaitHour = (now.getUTCHours() + 3) % 24; // الكويت = UTC+3
  const isAutoSlot = now.getUTCDay() === AUTO_PUBLISH_DAY && kuwaitHour === AUTO_PUBLISH_HOUR_KW;
  if (!isAutoSlot) return;

  if (env.DB) {
    const lastAuto = await env.DB.prepare(
      "SELECT scheduled_time FROM scheduled_posts WHERE caption LIKE '%[auto]%' ORDER BY id DESC LIMIT 1"
    ).first();
    if (lastAuto) {
      const lastTime = new Date(lastAuto.scheduled_time + ":00Z");
      if (now.getTime() - lastTime.getTime() < AUTO_MIN_GAP_DAYS * 24 * 3600 * 1000) return;
    }
  }

  try {
    await autoPublishNext(env);
  } catch (e) {
    // أي خطأ هنا (مفتاح ناقص، صورة قالب مفقودة) ما يوقف باقي الكرون
  }
}

async function generateCaption(env, category) {
  const label = CATEGORY_LABELS_AR[category];
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": env.ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-haiku-4-5-20251001",
      max_tokens: 300,
      messages: [
        {
          role: "user",
          content:
            `اكتب كابشن قصير لبوست انستقرام لشركة فعاليات كويتية اسمها Tiger Event، عن مجال "${label}". ` +
            `أسلوب عربي كويتي دافئ واحترافي، مع إيموجي مناسب، وسطر موقع (الكويت)، ودعوة للتواصل، ` +
            `وهاشتاقات مناسبة بالنهاية (منها #TigerEvent). لا تكرر نفس صياغة كل مرة. رد بالكابشن فقط بدون أي مقدمة.`,
        },
      ],
    }),
  });
  const data = await res.json();
  if (!data.content || !data.content[0]) throw new Error("فشل توليد الكابشن: " + JSON.stringify(data));
  return data.content[0].text.trim();
}

/* نفس فكرة generateCaption لكن بدل ما تاخذ فئة ثابتة (أعراس/فعاليات...)،
   تاخذ وصف حر يكتبه المستخدم بصفحة AI Studio + نوع المنشور + الأسلوب. */
async function generateFreeCaption(env, brief, tone, postType) {
  const toneLabel = TONE_LABELS_AR[tone] || tone;
  const typeLabel = POST_TYPE_LABELS_AR[postType] || postType;
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-api-key": env.ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-haiku-4-5-20251001",
      max_tokens: 400,
      messages: [
        {
          role: "user",
          content:
            `اكتب كابشن إنستقرام لشركة فعاليات كويتية اسمها Tiger Event، لمنشور من نوع "${typeLabel}"، ` +
            `بأسلوب ${toneLabel}. وصف الفعالية: "${brief}". ` +
            `اكتب بالعربي الكويتي الدافئ، مع إيموجي مناسب، سطر موقع (الكويت)، دعوة للتواصل، وهاشتاقات مناسبة بالنهاية (منها #TigerEvent). ` +
            `رد بالكابشن فقط بدون أي مقدمة أو شرح.`,
        },
      ],
    }),
  });
  const data = await res.json();
  if (!data.content || !data.content[0]) throw new Error("فشل توليد الكابشن: " + JSON.stringify(data));
  return data.content[0].text.trim();
}

async function autoPublishNext(env) {
  if (!env.DB || !env.IMAGES || !env.IG_ACCESS_TOKEN || !env.ANTHROPIC_API_KEY) {
    throw new Error("إعداد ناقص (DB / IMAGES / IG_ACCESS_TOKEN / ANTHROPIC_API_KEY)");
  }

  /* الفئة تتحدد بعدد البوستات التلقائية السابقة، لا برقم اليوم.
     الطريقة القديمة كانت (رقم اليوم % 4)، وهي تشتغل مع النشر ثلاث مرات بالأسبوع
     لكنها تنهار مع فاصل 14 يوم: 14 % 4 = 2، فتتناوب الفئات بين اثنتين فقط
     وتُهمل الاثنتين الباقيتين للأبد. العدّاد يضمن دورة كاملة على الأربع. */
  let autoCount = 0;
  const countRow = await env.DB.prepare(
    "SELECT COUNT(*) AS n FROM scheduled_posts WHERE caption LIKE '%[auto]%'"
  ).first();
  autoCount = (countRow && countRow.n) || 0;
  const category = CATEGORIES[autoCount % CATEGORIES.length];

  const listed = await env.IMAGES.list({ limit: 100 });
  const match = listed.objects.find((o) => o.key.toLowerCase().includes(category.toLowerCase()));
  if (!match) throw new Error(`ما لقيت صورة تحتوي كلمة "${category}" بالاسم — تأكد من رفع صورة القالب لهالفئة`);
  const mediaKey = match.key;

  /* لا يوجد هنا فحص "آخر 20 ساعة" الذي كان بالنسخة السابقة: مع فاصل أسبوعين
     صار بلا فائدة، وكان يقدر يمنع نشرًا مشروعًا. منع التكرار مسؤولية
     maybeAutoPublish وحدها الآن، ومكان واحد للقاعدة أوضح من مكانين. */

  const caption = (await generateCaption(env, category)) + "\n\n[auto]";
  const mediaUrl = `https://${WORKER_HOST}/img/${mediaKey}`;

  const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
  const meData = await meRes.json();
  if (!meData.id) throw new Error("معرف الحساب: " + JSON.stringify(meData));

  const containerRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media`, {
    method: "POST",
    body: new URLSearchParams({ image_url: mediaUrl, caption, access_token: env.IG_ACCESS_TOKEN }),
  });
  const containerData = await containerRes.json();
  if (!containerData.id) throw new Error("إنشاء الحاوية: " + JSON.stringify(containerData));

  const publishRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media_publish`, {
    method: "POST",
    body: new URLSearchParams({ creation_id: containerData.id, access_token: env.IG_ACCESS_TOKEN }),
  });
  const publishData = await publishRes.json();
  if (!publishData.id) throw new Error("النشر: " + JSON.stringify(publishData));

  await env.DB.prepare(
    "INSERT INTO scheduled_posts (media_key, media_type, caption, scheduled_time, status, post_id) VALUES (?, 'image', ?, ?, 'posted', ?)"
  ).bind(mediaKey, caption, new Date().toISOString().slice(0, 16), publishData.id).run();

  return { category, caption, mediaKey, postId: publishData.id };
}

async function runScheduledPosts(env) {
  if (!env.DB || !env.IMAGES || !env.IG_ACCESS_TOKEN) return;
  const now = new Date().toISOString();
  const { results } = await env.DB.prepare(
    "SELECT * FROM scheduled_posts WHERE status = 'pending' AND scheduled_time <= ? ORDER BY scheduled_time ASC"
  ).bind(now.slice(0, 16)).all();

  for (const post of results) {
    try {
      const result = await publishMediaKey(env, post.media_key, post.media_type, post.caption || "");
      await env.DB.prepare("UPDATE scheduled_posts SET status = 'posted', post_id = ? WHERE id = ?")
        .bind(result.postId, post.id).run();
    } catch (e) {
      await env.DB.prepare("UPDATE scheduled_posts SET status = 'failed', error_message = ? WHERE id = ?")
        .bind(String(e), post.id).run();
    }
  }
}

/* منطق نشر موحّد (إنشاء حاوية + انتظار معالجة الفيديو لو لزم + نشر نهائي)،
   يستخدمه كل من: runScheduledPosts (الجدولة التلقائية) و
   /api/publish-existing (النشر الفوري من لوحة التحكم لملف موجود بالمكتبة). */
async function publishMediaKey(env, key, mediaType, caption) {
  const mediaUrl = `https://${WORKER_HOST}/img/${key}`;
  const meRes = await fetch(`https://graph.instagram.com/me?fields=id&access_token=${env.IG_ACCESS_TOKEN}`);
  const meData = await meRes.json();
  if (!meData.id) throw new Error("معرف الحساب: " + JSON.stringify(meData));

  const isVideo = mediaType === "video";
  const containerParams = isVideo
    ? { media_type: "REELS", video_url: mediaUrl, caption: caption || "", access_token: env.IG_ACCESS_TOKEN }
    : { image_url: mediaUrl, caption: caption || "", access_token: env.IG_ACCESS_TOKEN };

  const containerRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media`, {
    method: "POST",
    body: new URLSearchParams(containerParams),
  });
  const containerData = await containerRes.json();
  if (!containerData.id) throw new Error("إنشاء الحاوية: " + JSON.stringify(containerData));

  if (isVideo) {
    let ready = false;
    for (let i = 0; i < 20; i++) {
      await new Promise((r) => setTimeout(r, 5000));
      const statusRes = await fetch(`https://graph.instagram.com/v21.0/${containerData.id}?fields=status_code&access_token=${env.IG_ACCESS_TOKEN}`);
      const statusData = await statusRes.json();
      if (statusData.status_code === "FINISHED") { ready = true; break; }
      if (statusData.status_code === "ERROR") throw new Error("فشلت معالجة الملف");
    }
    if (!ready) throw new Error("استغرقت المعالجة وقت طويل");
  }

  const publishRes = await fetch(`https://graph.instagram.com/v21.0/${meData.id}/media_publish`, {
    method: "POST",
    body: new URLSearchParams({ creation_id: containerData.id, access_token: env.IG_ACCESS_TOKEN }),
  });
  const publishData = await publishRes.json();
  if (!publishData.id) throw new Error("النشر: " + JSON.stringify(publishData));

  return { postId: publishData.id };
}

function errorBlock(title, detail) {
  return `<h1>⚠️ ${title}</h1><pre>${escapeHtml(detail)}</pre>`;
}

function escapeHtml(s) {
  return s.replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
}

function json(obj) {
  return new Response(JSON.stringify(obj), { headers: { "content-type": "application/json" } });
}

function html(body) {
  return new Response(
    `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Tiger Event — Instagram Token</title>
<style>
  body { background:#0B1A2E; color:#fff; font-family:'Segoe UI',Tahoma,sans-serif; padding:28px 18px; line-height:1.7; }
  h1 { font-size:20px; color:#F8A337; }
  .btn { display:inline-block; margin-top:16px; background:#F8A337; color:#0B1A2E; font-weight:700;
         padding:14px 22px; border-radius:10px; text-decoration:none; }
  textarea { width:100%; min-height:110px; margin-top:14px; background:#101F38; color:#7CE0A0;
             border:1px solid #2E7D4F; border-radius:10px; padding:12px; font-family:monospace;
             font-size:13px; direction:ltr; text-align:left; }
  pre { background:#101F38; border:1px solid #1E3050; border-radius:10px; padding:14px;
        white-space:pre-wrap; direction:ltr; text-align:left; font-size:13px; }
  .note { color:#9FB0C8; font-size:13px; }
</style>
</head>
<body>${body}</body>
</html>`,
    { headers: { "content-type": "text/html; charset=UTF-8" } }
  );
}

